import { randomUUID } from 'node:crypto'
import { createReadStream } from 'node:fs'
import { mkdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'

/**
 * Private file storage on local disk (development). Nothing here is reachable by URL;
 * files are streamed by the API after a permission check. Keys are generated by the
 * server only, so user input never becomes part of a path. Swapping this module is the
 * route to S3-compatible storage later.
 */
const KEY_PATTERN =
  /^(?:[0-9a-f-]{36}\/\d{4}\/[0-9a-f-]{36}(-thumb)?\.webp|documents\/[0-9a-f-]{36}\/\d{4}\/[0-9a-f-]{36}\.(?:pdf|jpg|png)|customers\/[0-9a-f-]{36}\/\d{4}\/[0-9a-f-]{36}\.bin|rentals\/[0-9a-f-]{36}\/\d{4}\/[0-9a-f-]{36}(-thumb)?\.webp)$/

export function createStorage(root: string) {
  const resolve = (key: string) => {
    if (!KEY_PATTERN.test(key)) throw new Error('Invalid storage key')
    const full = path.resolve(root, key)
    if (!full.startsWith(path.resolve(root) + path.sep)) throw new Error('Storage key escapes the root')
    return full
  }
  return {
    root,
    newKeys(companyId: string) {
      const id = randomUUID()
      const dir = `${companyId}/${new Date().getUTCFullYear()}`
      return { main: `${dir}/${id}.webp`, thumb: `${dir}/${id}-thumb.webp` }
    },
    /** Handover and return evidence photos (rentals): own prefix, apart from promotional photos. */
    newRentalPhotoKeys(companyId: string) {
      const id = randomUUID()
      const dir = `rentals/${companyId}/${new Date().getUTCFullYear()}`
      return { main: `${dir}/${id}.webp`, thumb: `${dir}/${id}-thumb.webp` }
    },
    /** Vehicle documents live under their own prefix, apart from promotional photos. */
    newDocumentKey(companyId: string, ext: 'pdf' | 'jpg' | 'png') {
      return `documents/${companyId}/${new Date().getUTCFullYear()}/${randomUUID()}.${ext}`
    },
    /** Customer document files (M2): encrypted bytes only; no extension or personal data in the name. */
    newCustomerFileKey(companyId: string, fileId: string) {
      return `customers/${companyId}/${new Date().getUTCFullYear()}/${fileId}.bin`
    },
    async readAll(key: string) {
      return readFile(resolve(key))
    },
    async put(key: string, data: Buffer) {
      const file = resolve(key)
      await mkdir(path.dirname(file), { recursive: true })
      await writeFile(file, data, { flag: 'wx' })
    },
    async open(key: string) {
      const file = resolve(key)
      const info = await stat(file)
      return { stream: createReadStream(file), size: info.size }
    },
    /** Replaces a stored file atomically (written next to it, then renamed over it): never a half-written file. */
    async replace(key: string, data: Buffer) {
      const file = resolve(key)
      const tmp = `${file}.${randomUUID()}.tmp`
      await writeFile(tmp, data, { flag: 'wx' })
      await rename(tmp, file)
    },
    async remove(...keys: string[]) {
      await Promise.all(keys.map((k) => rm(resolve(k), { force: true })))
    },
  }
}
export type Storage = ReturnType<typeof createStorage>
